package text

import (
	"testing"
)

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "nil width",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "negative width",
			text:  "hello world",
			width: -1,
			want:  nil,
		},
		{
			name:  "empty string",
			text:  "",
			width: 10,
			want:  nil,
		},
		{
			name:  "whitespace only",
			text:  "   \t\n  ",
			width: 10,
			want:  nil,
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 10,
			want:    []string{"hello"},
		},
		{
			name:  "two words fit on one line",
			text:  "hello world",
			width: 20,
			want:   []string{"hello world"},
		},
		{
			name:  "two words need two lines",
			text:  "hello world",
			width: 5,
			want:   []string{"hello", "world"},
		},
		{
			name:  "multiple words wrap correctly",
			text:  "the quick brown fox jumps over the lazy dog",
			width: 15,
			want:   []string{"the quick brown", "fox jumps over", "the lazy dog"},
		},
		{
			name:  "word longer than width gets own line",
			text:  "superlongword short",
			width: 5,
			want:   []string{"superlongword", "short"},
		},
		{
			name:  "runs of whitespace collapse",
			text:  "hello   world\t\teveryone",
			width: 20,
			want:   []string{"hello world everyone"},
		},
		{
			name:  "no trailing or leading spaces",
			text: "  hello   world  ",
			width: 20,
			want:   []string{"hello world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && tt.want == nil {
				return
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("got %v, want %v", got, tt.want)
			}
		})
	}
}
